const crypto = require('crypto');

// Handle Meta verification GET challenge
const method = $input.first().json.headers?.method || 'POST';
if (method === 'GET') {
  const mode = $input.first().json.query?.['hub.mode'];
  const token = $input.first().json.query?.['hub.verify_token'];
  const challenge = $input.first().json.query?.['hub.challenge'];
  if (mode === 'subscribe' && token === $env.META_WHATSAPP_VERIFY_TOKEN) {
    return [{json: {response: challenge}}];
  }
  throw new Error('Webhook verification failed');
}

// Verify X-Hub-Signature-256
const signature = $input.first().json.headers['x-hub-signature-256'];
const body = JSON.stringify($input.first().json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', $env.META_APP_SECRET).update(body).digest('hex');
if (signature !== expected) {
  throw new Error('Invalid webhook signature');
}

// Extract message data
const entry = $input.first().json.body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
if (!message || message.type !== 'text') {
  return []; // skip non-text messages
}

return [{json: {
  message_id: message.id,
  patient_phone: message.from,
  patient_message: message.text.body,
  phone_number_id: change.metadata.phone_number_id,
  timestamp: message.timestamp
}}];

// Check if idempotency insert returned 409 (duplicate)
const statusCode = $input.first().json.statusCode || $input.first().json.responseStatusCode;
if (statusCode === 409) {
  return []; // Already processed — stop silently
}

// Rate limiter: count messages in last 5 minutes
const supabaseUrl = $env.SUPABASE_URL;
const serviceKey = $env.SUPABASE_SERVICE_ROLE_KEY;
const clinicId = $json.clinic_id;
const patientPhone = $json.patient_phone;

const fiveMinAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
const countUrl = `${supabaseUrl}/rest/v1/conversations?clinic_id=eq.${clinicId}&patient_phone=eq.${patientPhone}&created_at=gte.${fiveMinAgo}&select=conversation_id`;

const response = await fetch(countUrl, {
  headers: {
    'apikey': serviceKey,
    'Authorization': `Bearer ${serviceKey}`,
    'Prefer': 'count=exact'
  }
});

const countHeader = response.headers.get('content-range');
const count = countHeader ? parseInt(countHeader.split('/')[1] || '0') : 0;

if (count >= 10) {
  return [{json: {
    rate_limited: true,
    safe_message: "Apologies, please slow down. Your messages are arriving too quickly. Try again in a few minutes.",
    patient_phone: patientPhone,
    phone_number_id: $json.phone_number_id
  }}];
}

return [{json: {
  rate_limited: false,
  message_id: $json.message_id,
  clinic_id: clinicId,
  patient_phone: patientPhone,
  patient_message: $json.patient_message,
  phone_number_id: $json.phone_number_id,
  timestamp: $json.timestamp
}}];

let msg = $json.patient_message;

// Strip control characters (keep newlines)
msg = msg.replace(/[\x00-\x09\x0b-\x1f]/g, '');

// Cap at 2000 characters
msg = msg.substring(0, 2000);

// Check prompt injection patterns
const injectionPatterns = [
  /ignore (all|previous) instructions/i,
  /you are now/i,
  /system prompt/i,
  /reveal your instructions/i,
  /forget everything/i,
  /new persona/i
];

const isInjection = injectionPatterns.some(p => p.test(msg));

if (isInjection) {
  return [{json: {
    injection_blocked: true,
    safe_message: "I'm sorry, I had trouble processing that. Could you please rephrase your question? Our team is here to help you book an appointment.",
    patient_phone: $json.patient_phone,
    phone_number_id: $json.phone_number_id
  }}];
}

return [{json: {
  injection_blocked: false,
  sanitized_message: msg,
  message_id: $json.message_id,
  clinic_id: $json.clinic_id,
  patient_phone: $json.patient_phone,
  phone_number_id: $json.phone_number_id,
  timestamp: $json.timestamp
}}];
